fn sort_order(order: &mut [i64], keys: &[str], vals: &[i64]) {
    let n = len(order)
    for i in 0..n {
        for j in 0..(n - 1 - i) {
            let a = order[j]
            let b = order[j + 1]
            let swap = vals[a] < vals[b] || (vals[a] == vals[b] && str_cmp(keys[a], keys[b]) > 0)
            if swap {
                order[j] = b
                order[j + 1] = a
            }
        }
    }
}

